package nl.smartstreamlabs.sbwdroneconfig;
import com.mojang.blaze3d.vertex.*;import com.mojang.blaze3d.systems.RenderSystem;import com.google.gson.*;
import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.texture.OverlayTexture;import net.minecraft.resources.ResourceLocation;import net.minecraft.core.*;import net.minecraft.world.phys.*;import org.joml.Matrix4f;
import java.util.*;import java.io.*;
@net.neoforged.fml.common.EventBusSubscriber(modid=SbwDroneRangeConfig.MOD_ID,value=net.neoforged.api.distmarker.Dist.CLIENT)
public final class NtRender {
 private static final ResourceLocation STRUCTURE=ResourceLocation.fromNamespaceAndPath(SbwDroneRangeConfig.MOD_ID,"textures/block/nt01_structure.png"),NET=ResourceLocation.fromNamespaceAndPath(SbwDroneRangeConfig.MOD_ID,"textures/block/nt01_net_cutout.png"),NET_LOD=ResourceLocation.fromNamespaceAndPath(SbwDroneRangeConfig.MOD_ID,"textures/block/nt01_net_lod.png"),POLE=ResourceLocation.fromNamespaceAndPath(SbwDroneRangeConfig.MOD_ID,"models/nt01/pole_mesh.json");
 private record Vertex(Vec3 p,float u,float v){}
 private record Face(Vertex a,Vertex b,Vertex c,boolean net){}
 private record Pole(Vec3 foot,Vec3 normal,double height){}
 private static final class Section {final BlockPos origin;final List<NtGeometry.Quad> panels=new ArrayList<>();final List<Pole> poles=new ArrayList<>();AABB bounds;VertexBuffer solid,net,lod;long used;int bytes,detailBytes;boolean far;Section(BlockPos p){origin=p;bounds=null;}void include(AABB b){bounds=bounds==null?b:bounds.minmax(b);}void dropDetail(){if(solid!=null){solid.close();solid=null;bytes-=detailBytes;gpuBytes-=detailBytes;detailBytes=0;}}void close(){if(solid!=null)solid.close();if(net!=null)net.close();if(lod!=null)lod.close();solid=net=lod=null;gpuBytes-=bytes;bytes=detailBytes=0;}}
 private static final class Model {NtTunnel tunnel;final List<Section> sections=new ArrayList<>();boolean preview,wholeInvalid;final List<Vec3> invalidSites=new ArrayList<>();void close(){for(var s:sections)s.close();}}
 private static final Map<UUID,Model> MODELS=new LinkedHashMap<>();private static Model preview;private static JsonArray pole;private static int gpuBytes;private static final Matrix4f DRAW_MATRIX=new Matrix4f();private static long frame;private static boolean compiledThisFrame;
 public static void update(NtTunnel t){remove(t.id());MODELS.put(t.id(),model(t,false));}
 public static void remove(UUID id){Model old=MODELS.remove(id);if(old!=null)old.close();}
 public static void clear(){for(var m:MODELS.values())m.close();MODELS.clear();clearPreview();}
 public static void clearPreview(){if(preview!=null)preview.close();preview=null;}
 public static void preview(NtTunnel t){clearPreview();if(t!=null)preview=model(t,true);}
 private static Model model(NtTunnel t,boolean transparent){Model m=new Model();m.tunnel=t;m.preview=transparent;if(transparent)for(String error:t.plan().errors()){var matcher=java.util.regex.Pattern.compile("(-?\\d+),\\s*(-?\\d+),\\s*(-?\\d+)").matcher(error);if(matcher.find())m.invalidSites.add(new Vec3(Double.parseDouble(matcher.group(1))+.5,Double.parseDouble(matcher.group(2))+.5,Double.parseDouble(matcher.group(3))+.5));else m.wholeInvalid=true;}var plan=t.plan();var path=new NtGeometry.Path(plan.points(),plan.settings());Map<Long,Section> sections=new LinkedHashMap<>();
  for(var q:NtGeometry.panels(path,plan)){var sec=section(sections,q.bounds().getCenter());sec.panels.add(q);sec.include(q.bounds());}
  for(int i=0;i<path.stations.length;i++){var f=path.frame(path.stations[i]);for(int sign:new int[]{-1,1}){Vec3 n=f.n().scale(sign),xz=f.p().add(n.scale(path.half));double foot=sign<0?plan.left().get(i):plan.right().get(i),height=f.p().y+plan.settings().height()+.60+plan.lift()-foot;var s=section(sections,new Vec3(xz.x,foot,xz.z));var p=new Pole(new Vec3(xz.x,foot,xz.z),n,height);s.poles.add(p);s.include(new AABB(xz.x-.5,foot,xz.z-.5,xz.x+.5,foot+height+.3,xz.z+.5));}}
  // Geometry is generated only when the route/revision changes; these cable quads reuse shared edge samples.
  for(int bay=0;bay<path.stations.length-1;bay++){double a=path.stations[bay],b=path.stations[bay+1];int rows=Math.max(2,(int)Math.ceil((b-a)/.75));for(int sign:new int[]{-1,1}){Vec3 last=NtGeometry.roof(path,plan,bay,a,sign);for(int r=1;r<=rows;r++){Vec3 next=NtGeometry.roof(path,plan,bay,a+(b-a)*r/rows,sign);tube(sections,last,next,.02);last=next;}}}
  for(int i=0;i<path.stations.length;i++){int bay=Math.min(i,path.stations.length-2);double s=path.stations[i];Vec3 last=NtGeometry.roof(path,plan,bay,s,-1);for(int c=1;c<=16;c++){Vec3 next=NtGeometry.roof(path,plan,bay,s,2*c/16.0-1);tube(sections,last,next,.018);last=next;}}
  m.sections.addAll(sections.values());return m;
 }
 private static Section section(Map<Long,Section> map,Vec3 at){int x=((int)Math.floor(at.x))>>4,y=((int)Math.floor(at.y))>>4,z=((int)Math.floor(at.z))>>4;long key=SectionPos.asLong(x,y,z);return map.computeIfAbsent(key,k->new Section(new BlockPos(x*16,y*16,z*16)));}
 private static void tube(Map<Long,Section> sections,Vec3 a,Vec3 b,double radius){Vec3 direction=b.subtract(a).normalize(),ref=Math.abs(direction.y)<.94?new Vec3(0,1,0):new Vec3(1,0,0),u=direction.cross(ref).normalize().scale(radius),v=direction.cross(u).normalize().scale(radius);for(int i=0;i<6;i++){Vec3 p=u.scale(Math.cos(i*Math.PI/3)).add(v.scale(Math.sin(i*Math.PI/3))),q=u.scale(Math.cos((i+1)*Math.PI/3)).add(v.scale(Math.sin((i+1)*Math.PI/3)));var face=new NtGeometry.Quad(a.add(p),a.add(q),b.add(q),b.add(p),false);var section=section(sections,face.bounds().getCenter());section.panels.add(face);section.include(face.bounds());}}
 private static JsonArray pole(){if(pole!=null)return pole;try(var stream=Minecraft.getInstance().getResourceManager().open(POLE);var reader=new InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)){pole=JsonParser.parseReader(reader).getAsJsonArray();return pole;}catch(IOException e){throw new IllegalStateException("NT-01 pole mesh missing",e);}}
 private static List<Face> poleFaces(Pole pole,boolean detailed){List<Face> out=new ArrayList<>();for(var element:pole()){var part=element.getAsJsonObject();String name=part.get("name").getAsString();if(!detailed&&!(name.endsWith("_lower")||name.endsWith("_upper")||name.endsWith("_socket")||name.endsWith("_foot")||name.endsWith("_cap")))continue;double cy=part.get("cy").getAsDouble();var faces=part.getAsJsonArray("triangles");for(var face:faces){var verts=face.getAsJsonArray();Vertex[] v=new Vertex[3];for(int i=0;i<3;i++){var a=verts.get(i).getAsJsonArray();double xx=a.get(0).getAsDouble(),yy=a.get(1).getAsDouble(),zz=a.get(2).getAsDouble(),h=pole.height;
    if(name.endsWith("_lower"))yy=.26+(yy-.26)*(h*.53-.26)/(5.1*.53-.26);
    else if(name.endsWith("_upper"))yy=h*.53-.1+(yy-(5.1*.53-.1))*(h+.15-(h*.53-.1))/(5.25-(5.1*.53-.1));
    else if(name.endsWith("_collar1")||name.endsWith("_collar_bolt1"))yy+=(h-5.1)*.53;
    else if(name.endsWith("_collar2")||name.endsWith("_collar_bolt2")||name.endsWith("_cap")||name.contains("_crown_eye")||name.contains("_tension_body")||name.contains("_threaded_tail"))yy+=h-5.1;
    else if(name.contains("_side_eye"))yy=yy-cy+cy/5.1*h;
    Vec3 n=pole.normal;Vec3 p=pole.foot.add(n.x*xx-n.z*zz,yy,n.z*xx+n.x*zz);v[i]=new Vertex(p,a.get(3).getAsFloat(),a.get(4).getAsFloat());}out.add(new Face(v[0],v[1],v[2],false));}}
  return out;
 }
 private static void compile(Section s,Model m){if(compiledThisFrame)return;compiledThisFrame=true;List<Face> solid=new ArrayList<>(),net=new ArrayList<>(),lod=new ArrayList<>();for(var q:s.panels){float u=q.net()?0:132/256f,v=q.net()?0:68/256f,du=q.net()?1:20/256f,dv=q.net()?1:20/256f;var a=new Vertex(q.a(),u,v+dv);var b=new Vertex(q.b(),u+du,v+dv);var c=new Vertex(q.c(),u+du,v);var d=new Vertex(q.d(),u,v);var list=q.net()?net:solid;list.add(new Face(a,b,c,q.net()));list.add(new Face(a,c,d,q.net()));}lod.addAll(solid);for(var p:s.poles){solid.addAll(poleFaces(p,true));lod.addAll(poleFaces(p,false));}
  int light=LevelRenderer.getLightColor(Minecraft.getInstance().level,BlockPos.containing(s.bounds.getCenter()));int color=m.preview?(m.tunnel.plan().valid()?0x7866ddff:0xaaff4444):0xffffffff;int base=(net.size()+lod.size())*4*36;if(gpuBytes+base>64*1024*1024){for(var cached:MODELS.values())for(var section:cached.sections)if(gpuBytes+base>64*1024*1024)section.dropDetail();if(preview!=null)for(var section:preview.sections)if(gpuBytes+base>64*1024*1024)section.dropDetail();}if(gpuBytes+base>64*1024*1024)return;boolean detail=gpuBytes+base+solid.size()*4*36<=64*1024*1024;if(!detail)solid.clear();s.solid=upload(solid,s.origin,color,light,m);s.net=upload(net,s.origin,color,light,m);s.lod=upload(lod,s.origin,color,light,m);s.detailBytes=solid.size()*4*36;s.bytes=(solid.size()+net.size()+lod.size())*4*36;gpuBytes+=s.bytes;
 }
 private static VertexBuffer upload(List<Face> faces,BlockPos origin,int color,int light,Model model){if(faces.isEmpty())return null;ByteBufferBuilder arena=new ByteBufferBuilder(Math.max(1024,faces.size()*4*36));BufferBuilder builder=new BufferBuilder(arena,VertexFormat.Mode.QUADS,DefaultVertexFormat.NEW_ENTITY);for(Face f:faces){int tint=color;if(model.preview&&!model.tunnel.plan().valid()&&!model.wholeInvalid){Vec3 centre=f.a.p.add(f.b.p).add(f.c.p).scale(1.0/3);tint=0x7866ddff;for(Vec3 site:model.invalidSites)if(centre.distanceToSqr(site)<2.5*2.5){tint=0xaaff4444;break;}}Vec3 n=f.b.p.subtract(f.a.p).cross(f.c.p.subtract(f.a.p)).normalize();for(Vertex v:new Vertex[]{f.a,f.b,f.c,f.c})builder.addVertex((float)(v.p.x-origin.getX()),(float)(v.p.y-origin.getY()),(float)(v.p.z-origin.getZ())).setColor(tint).setUv(v.u,v.v).setOverlay(OverlayTexture.NO_OVERLAY).setLight(light).setNormal((float)n.x,(float)n.y,(float)n.z);}var buffer=new VertexBuffer(VertexBuffer.Usage.STATIC);buffer.bind();buffer.upload(builder.buildOrThrow());arena.close();VertexBuffer.unbind();return buffer;}
 private static void draw(VertexBuffer buffer,RenderType type,Matrix4f view,Matrix4f projection){if(buffer==null)return;type.setupRenderState();buffer.bind();buffer.drawWithShader(view,projection,RenderSystem.getShader());VertexBuffer.unbind();type.clearRenderState();}
 @net.neoforged.bus.api.SubscribeEvent(priority=net.neoforged.bus.api.EventPriority.HIGH) public static void render(net.neoforged.neoforge.client.event.RenderLevelStageEvent e){if(e.getStage()!=net.neoforged.neoforge.client.event.RenderLevelStageEvent.Stage.AFTER_BLOCK_ENTITIES)return;var mc=Minecraft.getInstance();if(mc.level==null)return;frame++;compiledThisFrame=false;boolean builder=mc.player!=null&&mc.player.getMainHandItem().is(AddonItems.NT01_BUILDER.get());List<Model> models=new ArrayList<>(MODELS.values());if(builder&&preview!=null)models.add(preview);Vec3 camera=e.getCamera().getPosition();var poses=e.getPoseStack();
  for(Model m:models)for(Section s:m.sections){double dist=camera.distanceToSqr(s.bounds.getCenter());if(dist>160*160||!e.getFrustum().isVisible(s.bounds)){if(s.solid!=null&&frame-s.used>180)s.close();continue;}s.used=frame;if(s.solid==null&&s.lod==null&&s.net==null)compile(s,m);poses.pushPose();try{poses.translate(s.origin.getX()-camera.x,s.origin.getY()-camera.y,s.origin.getZ()-camera.z);var view=DRAW_MATRIX.set(RenderSystem.getModelViewMatrix()).mul(poses.last().pose());RenderType metal=m.preview?RenderType.entityTranslucent(STRUCTURE):RenderType.entityCutoutNoCull(STRUCTURE);if(dist>48*48)s.far=true;else if(dist<40*40)s.far=false;ResourceLocation netTexture=s.far?NET_LOD:NET;RenderType net=m.preview?RenderType.entityTranslucent(netTexture):RenderType.entityCutoutNoCull(netTexture);draw(dist>72*72||s.solid==null?s.lod:s.solid,metal,view,e.getProjectionMatrix());draw(s.net,net,view,e.getProjectionMatrix());}finally{poses.popPose();}}
  if(builder){var buffers=mc.renderBuffers().bufferSource();var lines=buffers.getBuffer(RenderType.lines());poses.pushPose();poses.translate(-camera.x,-camera.y,-camera.z);for(int i=0;i<NtClient.points.size();i++){Vec3 p=NtClient.points.get(i);LevelRenderer.renderLineBox(poses,lines,new AABB(p.x-.12,p.y+.03,p.z-.12,p.x+.12,p.y+.35,p.z+.12),i==NtClient.selected?1:.3f,.9f,.8f,1);}poses.popPose();buffers.endBatch(RenderType.lines());}
  if(gpuBytes>64*1024*1024){List<Section> all=new ArrayList<>();for(var m:models)all.addAll(m.sections);all.sort(Comparator.comparingLong(s->s.used));for(var s:all)if(gpuBytes>56*1024*1024&&s.used<frame)s.close();}
 }
 @net.neoforged.bus.api.SubscribeEvent public static void reload(net.neoforged.neoforge.client.event.RegisterClientReloadListenersEvent e){e.registerReloadListener((net.minecraft.server.packs.resources.ResourceManagerReloadListener)manager->{var saved=preview==null?null:preview.tunnel;clear();pole=null;for(var t:NtClient.TUNNELS.values())update(t);if(saved!=null)preview(saved);});}
}
